export interface SlugifyOptions {
  /** Remove leading and trailing whitespace before slugifying. */
  trim?: boolean;
}

export function slugify(value: string, options: SlugifyOptions = {}): string {
  const prepared = options.trim ? value.trim() : value;
  return prepared.toLowerCase().replace(/\s+/g, "-");
}

test("slugifies a phrase", () => {
  expect(slugify("Hello World")).toBe("hello-world");
});

test("removes leading and trailing whitespace when trim is set", () => {
  expect(slugify("  Hello World  ", { trim: true })).toBe("hello-world");
  expect(slugify("\n\tHello World\n", { trim: true })).toBe("hello-world");
});

test("keeps leading and trailing whitespace by default", () => {
  expect(slugify("  Hello World  ")).toBe("-hello-world-");
});

