export interface SlugifyOptions {
  /**
   * Remove leading and trailing whitespace before slugifying.
   * @default false
   */
  trim?: boolean;
}

export function slugify(value: string, options: SlugifyOptions = {}): string {
  const { trim = false } = options;
  const source = trim ? value.trim() : value;
  return source.toLowerCase().replace(/\s+/g, "-");
}

